import{obterJSON,endereco,consultaLimpa,pontuarCorrespondencia,idiomas}from'./comum.js';
export function converterInternetArchive(item){
 const id=String(item?.identifier||'').trim();if(!id)return null;
 const titulo=Array.isArray(item.title)?item.title[0]:item.title||'Sem título',autores=Array.isArray(item.creator)?item.creator:[item.creator].filter(Boolean),langs=idiomas(Array.isArray(item.language)?item.language:[item.language].filter(Boolean));
 const ler=endereco(`https://archive.org/details/${encodeURIComponent(id)}`),capa=endereco(`https://archive.org/services/img/${encodeURIComponent(id)}`);if(!ler)return null;
 return{id:`archive:${id}`,fonte:'archive',provedor:'Internet Archive',titulo:String(titulo),autores:autores.map(String),idiomas:langs,capa,descricao:Array.isArray(item.description)?String(item.description[0]||''):String(item.description||''),acessoLivre:true,dominioPublico:false,tipoAcesso:'Leitura / download aberto',licenca:'Item sem restrição de acesso encontrado no Internet Archive. Os direitos de reutilização dependem da edição e devem ser conferidos na página da obra.',origem:ler,ler,texto:null,formatos:[],downloads:Number(item.downloads)||0};
}
export async function pesquisarInternetArchive(q,o={}){const termo=consultaLimpa(q);if(!termo)return{livros:[],total:0,temMais:false};const pagina=Math.max(1,o.pagina||1),u=new URL('/api/acervos-gratuitos',location.origin);u.searchParams.set('fonte','archive');u.searchParams.set('q',termo);u.searchParams.set('pagina',String(pagina));const d=await obterJSON(u,13000,2),docs=Array.isArray(d?.response?.docs)?d.response.docs:[],total=Number(d?.response?.numFound)||docs.length,livros=docs.map(converterInternetArchive).filter(Boolean);for(const l of livros)l.relevancia=pontuarCorrespondencia(termo,l.titulo,l.autores);livros.sort((a,b)=>(b.relevancia||0)-(a.relevancia||0));return{livros,total,temMais:pagina*20<total&&docs.length>0}}
